window.docContents[152].resolve({"/Basic-Types/Strings/#Lean-__________________--Basic-Types--Strings--API-Reference--Raw-Substrings--Comparisons":{"contents":"Checks whether two substrings represent equal strings. Usually accessed via the == operator.Two substrings do not need to have the same underlying string or the same start and end positions;\ninstead, they are equal if they contain the same sequence of characters.\n\nChecks whether two substrings have the same position and content.The two substrings do not need to have the same underlying string for this check to succeed.\n\n","context":"Lean 中文参考手册\u0009Basic Types\u0009Strings\u0009API Reference\u0009Raw Substrings","header":"20.8.4.12.4. Comparisons","id":"/Basic-Types/Strings/#Lean-__________________--Basic-Types--Strings--API-Reference--Raw-Substrings--Comparisons"},"/Build-Tools-and-Distribution/Managing-Toolchains-with-Elan/#elan-toolchain-versions":{"contents":"When using Elan, the version of each tool on the PATH is a proxy that invokes the correct version.\nThe proxy determines the appropriate toolchain version for the current context, ensures that it is installed, and then invokes the underlying tool in the appropriate toolchain installation.\nThese proxies can be instructed to use a specific version by passing it as an argument prefixed with +, so lake +4.0.0 invokes lake version 4.0.0, after installing it if necessary.\n\n\n\n\n\n","context":"Lean 中文参考手册\u0009Build Tools\u0009Elan","header":"24.2.1. Selecting Toolchains","id":"/Build-Tools-and-Distribution/Managing-Toolchains-with-Elan/#elan-toolchain-versions"}});